function ComparisonTable({ products }: { products: Product[] }) {
  const sorted = [...products].sort((a, b) => a.price - b.price);
  const avgPrice = products.reduce((s, p) => s + p.price, 0) / products.length;
  const totalReviews = products.reduce((s, p) => s + p.reviews, 0);
  const bestRated = products.reduce((best, p) =>
    !best || p.rating > best.rating ? p : best,
    undefined as Product | undefined,
  );
  const cheapest = products.reduce((cheap, p) =>
    !cheap || p.price < cheap.price ? p : cheap,
    undefined as Product | undefined,
  );

  return (
    <div className="bg-white rounded-xl shadow-md p-6">
      <h2 className="text-xl font-bold mb-4">Comparison Overview</h2>

