  const configPromise = fetchConfigFromService();
  const user = await fetchUserFromService();
  // Kick off profile as soon as we have user.id, then await both together.
  const [profile, config] = await Promise.all([
    fetchProfileFromService(user.id),
    configPromise,
  ]);

  return NextResponse.json({
    success: true,
    user: { id: user.id, name: user.name },
    profile,
    config: { currency: config.currency },
  });
}
