  { id: '3', name: 'Studio Monitor', price: 449.99, category: 'Electronics', rating: 4.8, reviews: 567, inStock: false },
  { id: '4', name: 'Portable Speaker', price: 79.99, category: 'Electronics', rating: 4.0, reviews: 2100, inStock: true },
  { id: '5', name: 'Noise Canceling Pro', price: 379.99, category: 'Electronics', rating: 4.7, reviews: 890, inStock: true },
];

// Lazy-load mathjs-heavy analysis only when the user opens the Advanced tab.
const AdvancedAnalysis = dynamic(() => import('./AdvancedAnalysis'), {
  ssr: false,
  loading: () => (
    <div className="bg-white rounded-xl shadow-md p-6">Loading analysis…</div>
  ),
});

function ComparisonTable({ products }: { products: Product[] }) {
  const sorted = [...products].sort((a, b) => a.price - b.price);
  const avgPrice = products.reduce((s, p) => s + p.price, 0) / products.length;
  const totalReviews = products.reduce((s, p) => s + p.reviews, 0);
  const bestRated = products.reduce((best, p) =>
    !best || p.rating > best.rating ? p : best,
    undefined as Product | undefined,
  );
  const cheapest = products.reduce((cheap, p) =>
    !cheap || p.price < cheap.price ? p : cheap,
    undefined as Product | undefined,
  );

  return (
    <div className="bg-white rounded-xl shadow-md p-6">
