export function ProductList({ products, reviews }: Props) {
  const [cart, setCart] = useState<string[]>([]);
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState<'price' | 'rating'>('price');

  // Precompute review counts once per reviews change (O(reviews) instead of O(products*reviews) per render).
  const reviewCountById = useMemo(() => {
    const counts = new Map<string, number>();
    for (const r of reviews) {
      counts.set(r.productId, (counts.get(r.productId) ?? 0) + 1);
