import { NextRequest, NextResponse } from 'next/server';
import {
  fetchUserFromService,
  fetchConfigFromService,
  fetchProfileFromService,
} from '@/services/api-client';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => ({}));

  // Start config immediately; it doesn't depend on user.
  const configPromise = fetchConfigFromService();
  const user = await fetchUserFromService();
  // Kick off profile as soon as we have user.id, then await both together.
  const [profile, config] = await Promise.all([
    fetchProfileFromService(user.id),
    configPromise,
  ]);

  return NextResponse.json({
    success: true,
    user: { id: user.id, name: user.name },
    profile,
    config: { currency: config.currency },
  });
}
